INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李克用遣李袭吉谢恩，密请乘胜取凤翔", "start_year": 895, "end_year": 895, "time_original": "895年十二月晋王封爵以后；确日未载", "dynasty": "唐", "description": "李克用派掌书记李袭吉入朝谢恩，并密请乘胜攻取凤翔，称军在渭北等待决定。", "phases": [], "location_name": "朝廷、渭北", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1594808c-6222-5f46-8bdf-e8ca19cfd8e5"}, {"title": "皇帝询贵近，有人忧灭茂贞后沙陀过盛", "start_year": 895, "end_year": 895, "time_original": "895年十二月李袭吉使后条；确日未载", "dynasty": "唐", "description": "唐昭宗询问亲近者，有人称李茂贞若灭，沙陀势力将太盛、朝廷会危险。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a002d54e-0221-5661-991d-365a8ddae48e"}, {"title": "昭宗诏褒李克用，令休兵息民", "start_year": 895, "end_year": 895, "time_original": "895年十二月议讨后条；确日未载", "dynasty": "唐", "description": "唐昭宗诏褒李克用忠诚，称王行瑜罪最重，茂贞韩建知罪并继续贡奉，应暂休兵。李克用奉诏停止请讨后的进攻计划。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "eab31550-a4c9-529b-9511-8b3ac5cbdd48"}, {"title": "李克用私谓诏使朝廷疑己，茂贞不去关中难安", "start_year": 895, "end_year": 895, "time_original": "895年十二月奉诏后条；确日未载", "dynasty": "唐", "description": "李克用私下对诏使说朝廷似疑自己有异心，李茂贞不除，关中不会安宁。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "ff0827ab-ec82-5aa4-a302-ecc2eb7b9909"}, {"title": "朝廷免李克用入朝，将佐劝其入见", "start_year": 895, "end_year": 895, "time_original": "895年十二月奉诏后条；确日未载", "dynasty": "唐", "description": "朝廷诏免李克用入朝，将佐有人认为已近京师应入见，李克用犹豫未决。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "c1411372-517a-5724-b8d3-e07b9bfcfebd"}, {"title": "盖寓劝李克用勿率兵渡渭惊京城", "start_year": 895, "end_year": 895, "time_original": "895年十二月入朝争议时；确日未载", "dynasty": "唐", "description": "盖寓劝李克用，天子未安、人心尚危，率兵渡渭恐再惊京城；人臣尽忠在勤王而非入觐，应慎重考虑。李克用笑称盖寓尚不愿自己入朝，何况天下人。", "phases": [], "location_name": "渭北、京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bb0af359-255c-54f6-b54a-39a3fdf21abf"}, {"title": "李克用上表不敢径入朝，忧军扰居民", "start_year": 895, "end_year": 895, "time_original": "895年十二月辛亥以前；确日未载", "dynasty": "唐", "description": "李克用表称统率大军，不敢直接入朝，又恐部落士卒侵扰渭北居民。", "phases": [], "location_name": "朝廷、渭北", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "717a24be-7800-5482-bf1a-77029b684409"}, {"title": "李克用辛亥率军东归，奏表至京上下始安", "start_year": 895, "end_year": 895, "time_original": "895年十二月辛亥", "dynasty": "唐", "description": "李克用率军东归，奏表到京师，朝廷上下才安定。", "phases": [], "location_name": "京师、东归途中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bbe4ee2b-1967-593c-a489-1ed5ee4a5341"}, {"title": "朝廷赐河东士卒三十万缗", "start_year": 895, "end_year": 895, "time_original": "895年十二月李克用东归条；确日未载", "dynasty": "唐", "description": "朝廷诏赐河东士卒钱三十万缗。", "phases": [], "location_name": "朝廷、河东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "521c9d0b-0f92-58fe-abe6-4c7492e2f22a"}, {"title": "李克用去后茂贞占河西州县，任胡敬璋", "start_year": 895, "end_year": 895, "time_original": "895年十二月李克用去后总述；起讫未另载", "dynasty": "唐", "description": "李克用离去后，史书称李茂贞仍骄横，河西多州县被其占据，他以胡敬璋为河西节度使。", "phases": [], "location_name": "河西州县", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "52d45ca4-ae4e-5a61-820b-19e61f266ad6"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

