INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "李克用派掌书记李袭吉入朝谢恩，并密请乘胜攻取凤翔，称军在渭北等待决定。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p069·原文件第74行", "note": "原文：李克用遣掌书记李袭吉入谢恩，密言于上曰：“比年以来，关辅不宁，乘此胜势，遂取凤翔，一劳永逸，时不可失。臣屯军渭北，专俟进止。”；核对说明：密言为李克用请求，俟进止非已获批准，一劳永逸为其主张。", "status": "draft", "id": "ec4f96f4-dc02-54f8-bd2f-8ea28c6a34e3", "subject_id": "1594808c-6222-5f46-8bdf-e8ca19cfd8e5", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "895年十二月晋王封爵以后；确日未载", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p069·原文件第74行", "note": "原文：李克用遣掌书记李袭吉入谢恩，密言于上曰：“比年以来，关辅不宁，乘此胜势，遂取凤翔，一劳永逸，时不可失。臣屯军渭北，专俟进止。”；核对说明：密言为李克用请求，俟进止非已获批准，一劳永逸为其主张。", "status": "draft", "id": "2c885304-cf63-564e-9d6b-d281e44414f2", "subject_id": "1594808c-6222-5f46-8bdf-e8ca19cfd8e5", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李克用：遣使请讨者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p069·原文件第74行", "note": "原文：李克用遣掌书记李袭吉入谢恩，密言于上曰：“比年以来，关辅不宁，乘此胜势，遂取凤翔，一劳永逸，时不可失。臣屯军渭北，专俟进止。”上谋于贵近，或曰：“茂贞复灭，则沙陀大盛，朝廷危矣！”上乃赐克用诏，褒其忠款，而言：“不臣之状，行瑜为甚。自朕出幸以来，茂贞、韩建自知其罪，不忘国恩，职贡相继，且当休兵息民。”克用奉诏而止。既而私于诏使曰：“观朝廷之意，似疑克用有异心也。然不去茂贞，关中无安宁之日。”又诏免克用入朝，将佐或言：“今密迩阙庭，岂可不入见天子，！”克用犹豫未决，盖寓言于克用曰：“向者王行瑜辈纵兵狂悖，致銮舆播越，百姓奔散。今天子还未安席，人心尚危，大王若引兵渡渭，窃恐复惊骇都邑。人臣尽忠，在于勤王，不在入觐，愿熟图之！”克用笑曰：“盖寓尚不欲吾入朝，况天下之人乎！”乃表称：“臣总帅大军，不敢径入朝觐，且惧部落士卒侵扰渭北居人。”辛亥，引兵东归。表至京师，上下始安。诏赐河东士卒钱三十万缗。克用既去，李茂贞骄横如故，河西州县多为茂贞所据，以其将胡敬璋为河西节度使。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "55b9b747-9237-59db-896c-6206191398ce", "subject_id": "04af206e-fa86-581c-86b9-87a78a8d59a5", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李克用：遣使请讨者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p069·原文件第74行", "note": "原